def galois_test(D, K, z, m, verbose=False):
    gens = [Integer(g) for g in Zmod(m).unit_gens()]
    for t in gens:
        r = (K.hom([z**t])(D)/D)
        sq = r.is_square()
        if verbose: print(f"    sigma_{t}(D)/D is_square = {sq}")
        if not sq:
            return False, t
    return True, None

